package org.apache.commons.math3.geometry.euclidean.threed;

import org.apache.commons.math3.geometry.euclidean.threed.Line;
import org.apache.commons.math3.geometry.euclidean.threed.Vector3D;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Math_9_ast_edit_Test {

    @Test
    public void testReproduceBug() throws MathIllegalArgumentException {
        // Create a direction vector
        Vector3D direction = new Vector3D(1, 0, 0);
        // Create a point on the line
        Vector3D zero = new Vector3D(0, 0, 0);

        // Initialize the line using the constructor
        Line line = new Line(zero, direction);

        // Revert the line
        Line revertedLine = line.revert();

        // The direction of the reverted line should be the negation of the original direction
        Vector3D expectedRevertedDirection = direction.negate();
        Vector3D actualRevertedDirection = revertedLine.getDirection();

        // Debugging output
        System.out.println("Expected Reverted Direction: " + expectedRevertedDirection);
        System.out.println("Actual Reverted Direction: " + actualRevertedDirection);

        // Assert that the directions are equal by comparing components
        assertEquals("X component should be negated", expectedRevertedDirection.getX(), actualRevertedDirection.getX(), 1e-10);
        assertEquals("Y component should be negated", expectedRevertedDirection.getY(), actualRevertedDirection.getY(), 1e-10);
        assertEquals("Z component should be negated", expectedRevertedDirection.getZ(), actualRevertedDirection.getZ(), 1e-10);
    }
}

